import java.util.*;

public class Main {
    static double minCostToHireWorkers(int[] quality, int[] wage, int k) {
        int n = quality.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> Double.compare((double) wage[a] / quality[a], (double) wage[b] / quality[b]));

        double best = Double.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            double ratio = (double) wage[idx[i]] / quality[idx[i]];
            List<Integer> eligible = new ArrayList<>();
            for (int j = 0; j <= i; j++) eligible.add(quality[idx[j]]);
            Collections.sort(eligible);                    // re-sort from scratch each time
            if (eligible.size() >= k) {
                double sum = 0;
                for (int j = 0; j < k; j++) sum += eligible.get(j);
                best = Math.min(best, ratio * sum);
            }
        }
        return best;
    }
}

