import java.util.*;

public class Main {
    static double minCostToHireWorkers(int[] quality, int[] wage, int k) {
        int n = quality.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> Double.compare((double) wage[a] / quality[a], (double) wage[b] / quality[b]));

        PriorityQueue<Integer> maxHeap = new PriorityQueue<>(Collections.reverseOrder());
        long qualitySum = 0;
        double best = Double.MAX_VALUE;
        for (int i : idx) {
            double ratio = (double) wage[i] / quality[i];
            maxHeap.offer(quality[i]);
            qualitySum += quality[i];
            if (maxHeap.size() > k) {
                qualitySum -= maxHeap.poll();          // remove the largest quality
            }
            if (maxHeap.size() == k) {
                best = Math.min(best, ratio * qualitySum);
            }
        }
        return best;
    }
}

