using namespace std;

double minCostToHireWorkers(vector<int>& quality, vector<int>& wage, int k) {
    int n = quality.size();
    vector<int> idx(n);
    iota(idx.begin(), idx.end(), 0);
    sort(idx.begin(), idx.end(), [&](int a, int b) {
        return (double)wage[a] / quality[a] < (double)wage[b] / quality[b];
    });

    priority_queue<int> maxHeap;
    long long qualitySum = 0;
    double best = 1e18;
    for (int i : idx) {
        double ratio = (double)wage[i] / quality[i];
        maxHeap.push(quality[i]);
        qualitySum += quality[i];
        if ((int)maxHeap.size() > k) {
            qualitySum -= maxHeap.top(); maxHeap.pop();      // remove the largest quality
        }
        if ((int)maxHeap.size() == k) {
            best = min(best, ratio * (double)qualitySum);
        }
    }
    return best;
}
